(function () {
'use strict';
var doc = document;
function debounce(fn, wait) {
var timer = null;
return function () {
clearTimeout(timer);
timer = setTimeout(fn, wait);
};
}
function onMediaChange(query, handler) {
if (query.addEventListener) {
query.addEventListener('change', handler);
} else if (query.addListener) {
query.addListener(handler);
}
}
function initHeader() {
var header = doc.querySelector('[data-header]');
if (!header) {
return;
}
var stage = doc.querySelector('[data-carousel]');
if (header.classList.contains('site-header--overlay') && 'IntersectionObserver' in window) {
var sentinel = doc.createElement('div');
sentinel.setAttribute('aria-hidden', 'true');
sentinel.style.cssText = 'position:absolute;top:0;left:0;width:1px;height:48px;pointer-events:none;';
doc.body.insertBefore(sentinel, doc.body.firstChild);
new IntersectionObserver(function (entries) {
header.classList.toggle('is-scrolled', !entries[0].isIntersecting);
}).observe(sentinel);
} else if (header.classList.contains('site-header--overlay')) {
header.classList.add('is-scrolled');
}
if (stage && 'IntersectionObserver' in window) {
new IntersectionObserver(function (entries) {
doc.body.classList.toggle('hero-in-view', entries[0].isIntersecting);
}, { threshold: 0.4 }).observe(stage);
}
var toggle = header.querySelector('[data-menu-toggle]');
var nav = doc.getElementById('site-nav');
if (!toggle || !nav) {
return;
}
function setOpen(open) {
toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
header.classList.toggle('is-open', open);
}
toggle.addEventListener('click', function () {
setOpen(toggle.getAttribute('aria-expanded') !== 'true');
});
doc.addEventListener('keydown', function (event) {
if (event.key === 'Escape' && header.classList.contains('is-open')) {
setOpen(false);
toggle.focus();
}
});
var desktop = window.matchMedia('(min-width: 900px)');
onMediaChange(desktop, function () {
if (desktop.matches) {
setOpen(false);
}
});
}
function trackGlass(element) {
var frame = 0;
var lastEvent = null;
element.addEventListener('pointermove', function (event) {
lastEvent = event;
if (frame) {
return;
}
frame = window.requestAnimationFrame(function () {
frame = 0;
var rect = element.getBoundingClientRect();
if (!rect.width || !lastEvent) {
return;
}
var x = ((lastEvent.clientX - rect.left) / rect.width) * 100;
var y = ((lastEvent.clientY - rect.top) / rect.height) * 100;
element.style.setProperty('--glass-x', x.toFixed(1) + '%');
element.style.setProperty('--glass-y', y.toFixed(1) + '%');
});
});
}
function initSwitch(element) {
var capsule = element.querySelector('.switch__capsule');
var items = Array.prototype.slice.call(element.querySelectorAll('.switch__item'));
if (!capsule || !items.length) {
return;
}
function activeItem() {
return element.querySelector('.switch__item[aria-current="page"], .switch__item[aria-selected="true"]');
}
function moveTo(item) {
if (!item || !item.offsetWidth || window.getComputedStyle(capsule).display === 'none') {
element.classList.remove('has-capsule');
return;
}
var box = element.getBoundingClientRect();
var rect = item.getBoundingClientRect();
element.style.setProperty('--cap-x', (rect.left - box.left) + 'px');
element.style.setProperty('--cap-w', rect.width + 'px');
element.classList.add('has-capsule');
items.forEach(function (other) {
other.classList.toggle('is-highlighted', other === item);
});
}
function rest() {
var focused = doc.activeElement;
if (focused && items.indexOf(focused) !== -1 && focused.matches(':focus-visible')) {
moveTo(focused);
return;
}
var active = activeItem();
if (active) {
moveTo(active);
} else {
element.classList.remove('has-capsule');
items.forEach(function (other) {
other.classList.remove('is-highlighted');
});
}
}
function restWithoutAnimation() {
element.classList.add('no-anim');
rest();
element.getBoundingClientRect();
element.classList.remove('no-anim');
}
items.forEach(function (item) {
item.addEventListener('pointerenter', function (event) {
if (event.pointerType === 'mouse') {
moveTo(item);
}
});
item.addEventListener('focus', function () {
if (item.matches(':focus-visible')) {
moveTo(item);
}
});
item.addEventListener('blur', function () {
window.requestAnimationFrame(rest);
});
});
element.addEventListener('pointerleave', rest);
element.addEventListener('tt:sync', rest);
window.addEventListener('resize', debounce(restWithoutAnimation, 120));
if (doc.fonts && doc.fonts.ready) {
doc.fonts.ready.then(restWithoutAnimation);
}
trackGlass(element);
restWithoutAnimation();
}
var REVEAL = [
'.section-title:not(.section-head *):not(.features__head *):not(.specs-section__head *):not(.section-title--blur)',
'.section-head', '.dock', '.grid-cards > *', '.cta-band__inner',
'.features__head', '.features__track', '.specs-section__head', '.specs-section__body',
'.info-block', '.list-count'
].join(',');
function initReveal() {
if (!('IntersectionObserver' in window) || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
return;
}
var fold = window.innerHeight * 0.92;
var pending = [];
Array.prototype.forEach.call(doc.querySelectorAll(REVEAL), function (element) {
var parent = element.parentElement;
if (parent && parent.scrollWidth > parent.clientWidth + 1 && /auto|scroll/.test(window.getComputedStyle(parent).overflowX)) {
element = parent;
}
if (pending.indexOf(element) === -1 && element.getBoundingClientRect().top > fold) {
pending.push(element);
}
});
if (!pending.length) {
return;
}
function settle(element) {
element.classList.remove('reveal', 'is-in');
element.style.removeProperty('--reveal-delay');
}
var observer = new IntersectionObserver(function (entries) {
var order = 0;
entries.forEach(function (entry) {
if (!entry.isIntersecting) {
return;
}
var element = entry.target;
observer.unobserve(element);
element.style.setProperty('--reveal-delay', Math.min(order, 5) * 60 + 'ms');
order++;
element.classList.add('is-in');
element.addEventListener('transitionend', function done(event) {
if (event.target === element && event.propertyName === 'opacity') {
element.removeEventListener('transitionend', done);
settle(element);
}
});
});
}, { rootMargin: '0px 0px -8% 0px' });
pending.forEach(function (element) {
element.classList.add('reveal');
observer.observe(element);
});
}
function initSoftBlur() {
var title = doc.querySelector('[data-soft-blur]');
if (!title) {
return;
}
if (!('IntersectionObserver' in window)) {
title.classList.add('is-in');
return;
}
var observer = new IntersectionObserver(function (entries) {
if (entries[0].isIntersecting) {
observer.disconnect();
title.classList.add('is-in');
}
}, { threshold: 0.5 });
observer.observe(title);
}
function initWhy() {
var why = doc.querySelector('[data-why]');
if (!why) {
return;
}
if (!('IntersectionObserver' in window)) {
why.classList.add('is-in');
return;
}
var observer = new IntersectionObserver(function (entries) {
if (entries[0].isIntersecting) {
observer.disconnect();
why.classList.add('is-in');
}
}, { threshold: 0.25 });
observer.observe(why);
}
function initCatalogFilter() {
var nav = doc.querySelector('.filters__categories');
var list = doc.querySelector('.section--list');
var head = doc.querySelector('.page-head');
if (!nav || !list || !head || typeof window.fetch !== 'function' || !window.history.pushState) {
return;
}
var switchEl = nav.querySelector('[data-switch]');
var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
var ease = 'cubic-bezier(0.22, 1, 0.36, 1)';
var request = 0;
function markCurrent(url) {
Array.prototype.forEach.call(nav.querySelectorAll('.switch__item'), function (item) {
if (item.href === url) {
item.setAttribute('aria-current', 'page');
} else {
item.removeAttribute('aria-current');
}
});
if (switchEl) {
switchEl.dispatchEvent(new Event('tt:sync'));
}
}
function fadeOut() {
if (reduce.matches || typeof list.animate !== 'function') {
return Promise.resolve();
}
var frames = [
{ opacity: 1, filter: 'blur(0)', transform: 'none' },
{ opacity: 0, filter: 'blur(4px)', transform: 'translateY(6px)' }
];
var animations = [list, head].map(function (node) {
return node.animate(frames, { duration: 260, easing: ease, fill: 'forwards' });
});
return animations[0].finished.then(function () { return animations; });
}
function enter(outAnimations) {
(outAnimations || []).forEach(function (animation) {
animation.cancel();
});
if (reduce.matches || typeof list.animate !== 'function') {
return;
}
head.animate([
{ opacity: 0, filter: 'blur(4px)' },
{ opacity: 1, filter: 'blur(0)' }
], { duration: 520, easing: ease });
var count = list.querySelector('.list-count');
if (count) {
count.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 420, easing: ease });
}
Array.prototype.forEach.call(list.querySelectorAll('.grid-cards > *, .empty-state'), function (card, i) {
card.animate([
{ opacity: 0, filter: 'blur(6px)', transform: 'translateY(12px)' },
{ opacity: 1, filter: 'blur(0)', transform: 'none' }
], { duration: 680, delay: Math.min(i, 8) * 60, easing: ease, fill: 'backwards' });
});
}
function load(url, push) {
var id = ++request;
markCurrent(url);
var out = fadeOut();
var page = window.fetch(url, { credentials: 'same-origin' }).then(function (response) {
if (!response.ok) {
throw new Error('HTTP ' + response.status);
}
return response.text();
});
Promise.all([page, out]).then(function (result) {
if (id !== request) {
return;
}
var next = new DOMParser().parseFromString(result[0], 'text/html');
var nextList = next.querySelector('.section--list');
var nextHead = next.querySelector('.page-head');
if (!nextList || !nextHead) {
throw new Error('Respuesta sin listado');
}
list.innerHTML = nextList.innerHTML;
head.innerHTML = nextHead.innerHTML;
doc.title = next.title;
if (push) {
window.history.pushState({ ttCatalog: true }, '', url);
}
if (nav.getBoundingClientRect().top < 0) {
nav.scrollIntoView({ block: 'start', behavior: reduce.matches ? 'auto' : 'smooth' });
}
enter(result[1]);
}).catch(function () {
window.location.href = url;
});
}
nav.addEventListener('click', function (event) {
var link = event.target.closest ? event.target.closest('a.switch__item') : null;
if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
return;
}
event.preventDefault();
if (link.getAttribute('aria-current') === 'page' || link.href === window.location.href) {
return;
}
load(link.href, true);
});
window.history.replaceState({ ttCatalog: true }, '', window.location.href);
window.addEventListener('popstate', function (event) {
if (event.state && event.state.ttCatalog) {
load(window.location.href, false);
}
});
}
function init() {
initHeader();
initReveal();
initSoftBlur();
initWhy();
initCatalogFilter();
Array.prototype.forEach.call(doc.querySelectorAll('[data-switch]'), initSwitch);
Array.prototype.forEach.call(doc.querySelectorAll('.stage__arrow, .round-button'), trackGlass);
}
if (doc.readyState === 'loading') {
doc.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
